// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address and an array length indicator and a value; we cannot fuzz dynamic arrays directly here,
    // so we fuzz a single target address and a length to construct an array of that length filled with that address.
    function testFuzz_property(address from, address tosAddr, uint256 len) public {
        // admissible domain: require at least one recipient to satisfy require(_tos.length > 0)
        // but keep wide: allow many lengths; bound to a reasonable max to avoid huge loops in test runs
        uint256 boundedLen = bound(len, 1, 10);

        // build the _tos array of boundedLen, all entries = tosAddr
        address[] memory tos = new address[](boundedLen);
        for (uint i = 0; i < boundedLen; i++) {
            tos[i] = tosAddr;
        }

        // Call transfer and capture its returned boolean via try/catch to observe actual return behaviour.
        bool ok;
        try c.transfer(from, tosAddr, tos, 1) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General rule: for any non-empty _tos array the reference implementation returns true.
        // So assertTrue(ok) — the reference C satisfies this for all inputs; the mutant (which returns false)
        // will make this assertion fail for some inputs (any with boundedLen>=1).
        assertTrue(ok);
    }
}
